from scipy.optimize import least_squares
def Pk(deg):
    keep=[(i,j) for i in range(deg+1) for j in range(deg+1-i)]
    return np.column_stack([x**i*v**j for i,j in keep])
P4=Pk(4); P2=Pk(2)
def mdecay(p):
    w,b=p
    e=np.exp(-b*t); c=np.cos(w*t); s=np.sin(w*t)
    A=np.column_stack([P4,P2*(e*c)[:,None],P2*(e*s)[:,None]])
    co=np.linalg.lstsq(A,dv_dt,rcond=None)[0]; return np.mean((A@co-dv_dt)**2)/np.var(dv_dt)
def mtlin(p):
    w=p[0]; c=np.cos(w*t); s=np.sin(w*t)
    A=np.column_stack([P4,P2*(t*c)[:,None],P2*(t*s)[:,None],P2*c[:,None],P2*s[:,None]])
    co=np.linalg.lstsq(A,dv_dt,rcond=None)[0]; return np.mean((A@co-dv_dt)**2)/np.var(dv_dt)
def mharm(p):
    w=p[0]; A=[P4]
    for k in [1,2,3]:
        A+= [P2*np.cos(k*w*t)[:,None],P2*np.sin(k*w*t)[:,None]]
    A=np.column_stack(A)
    co=np.linalg.lstsq(A,dv_dt,rcond=None)[0]; return np.mean((A@co-dv_dt)**2)/np.var(dv_dt)
